#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# The wizard reads answers from /dev/tty, so it works even when stdin is
# redirected. Without a terminal every answer would be empty, so stop. Sourcing
# the library skips the check.
if [[ "${BASH_SOURCE[0]}" == "$0" ]] && ! { : </dev/tty; } 2>/dev/null; then
  echo "wizard: no terminal. Run this script yourself in a terminal, not from an agent's shell." >&2
  exit 1
fi

# ──────────────────────────────────────────────────────────────────────────
# Shared wizard library.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold 2>/dev/null || true); DIM=$(tput dim 2>/dev/null || true); RESET=$(tput sgr0 2>/dev/null || true)
  BLUE=$(tput setaf 4 2>/dev/null || true); GREEN=$(tput setaf 2 2>/dev/null || true); YELLOW=$(tput setaf 3 2>/dev/null || true); RED=$(tput setaf 1 2>/dev/null || true)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." shows, as a bullet, one action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else warn "couldn't open a browser; visit it manually: $url"; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ </dev/tty || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply </dev/tty || true
  [[ "$reply" =~ ^[Yy] ]]
}

# dotenv_encode VALUE prints VALUE in a form dotenv parsers read back
# unchanged: bare when it's plain, in double quotes with \n for newlines when
# it's multi-line (e.g. a PEM key), else in single quotes (literal, so # and $
# survive), else in double quotes. Node's parser expands only \n inside double
# quotes, and other parsers expand $ there, so a double-quoted value can't hold
# a ", \, or $. Fails on a value it can't quote.
dotenv_encode() {
  local value="$1" bare='^[A-Za-z0-9_./:@,+-]*$' nl=$'\n'
  if [[ "$value" =~ $bare ]]; then
    printf '%s' "$value"
  elif [[ "$value" == *"$nl"* ]]; then
    [[ "$value" != *[\"\\\$]* ]] || return 1
    printf '"%s"' "${value//$nl/\\n}"
  elif [[ "$value" != *"'"* ]]; then
    printf "'%s'" "$value"
  elif [[ "$value" != *[\"\\\$]* ]]; then
    printf '"%s"' "$value"
  else
    return 1
  fi
}

# dotenv_decode RAW undoes dotenv_encode on a value read from ENV_FILE,
# expanding \n inside double quotes as Node's parser does.
dotenv_decode() {
  local raw="$1"
  if (( ${#raw} >= 2 )) && [[ "$raw" == \'*\' ]]; then
    raw="${raw:1:${#raw}-2}"
  elif (( ${#raw} >= 2 )) && [[ "$raw" == \"*\" ]]; then
    raw="${raw:1:${#raw}-2}"
    raw="${raw//\\n/$'\n'}"
  fi
  printf '%s' "$raw"
}

# _DOTENV_AWK, run with -v key=KEY on ENV_FILE, finds KEY's assignments,
# including a quoted value that spans lines (a PEM key someone pasted). With
# -v mode=get it prints the last one's raw value, or fails when there's none.
# With -v mode=drop it prints the file without them. A value whose quote never
# closes is one line, as Node's dotenv reads it, so it can't swallow the rest.
# Inside double quotes, \" doesn't close the value.
# shellcheck disable=SC2016 # awk's $0, not the shell's
_DOTENV_AWK='
function closes(s, q,   i, c) {
  for (i = 1; i <= length(s); i++) {
    c = substr(s, i, 1)
    if (q == "\"" && c == "\\") { i++; continue }
    if (c == q) return i
  }
  return 0
}
{ lines[NR] = $0 }
END {
  i = 1
  while (i <= NR) {
    name = ""; value = ""; last = i
    assignment = lines[i]
    sub(/^[ \t]*(export[ \t]+)?/, "", assignment)
    if (match(assignment, /^[A-Za-z_][A-Za-z0-9_.-]*[ \t]*=[ \t]*/)) {
      name = substr(assignment, 1, RLENGTH)
      sub(/[ \t]*=.*/, "", name)
      value = substr(assignment, RLENGTH + 1)
      q = substr(value, 1, 1)
      if (q == "\"" || q == "\047") {
        if ((p = closes(substr(value, 2), q))) {
          value = substr(value, 1, p + 1)
        } else {
          joined = value
          for (k = i + 1; k <= NR; k++) {
            if ((p = closes(lines[k], q))) {
              value = joined "\n" substr(lines[k], 1, p); last = k; break
            }
            joined = joined "\n" lines[k]
          }
        }
      } else {
        sub(/#.*/, "", value)
        sub(/[ \t\r]+$/, "", value)
      }
    }
    if (name == key) { found = 1; got = value }
    else if (mode == "drop") for (k = i; k <= last; k++) print lines[k]
    i = last + 1
  }
  if (mode == "get") { if (!found) exit 1; printf "%s", got }
}'

# _existing KEY: current value of KEY in ENV_FILE, if any.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local raw; raw=$(awk -v mode=get -v key="$1" "$_DOTENV_AWK" "$ENV_FILE") || return 1
  dotenv_decode "$raw"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret).
ask() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -r input </dev/tty || true
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input </dev/tty || true
  printf '\n'
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# _warn_env_not_ignored warns once per run when ENV_FILE sits in a git repo
# that doesn't ignore it, since the values written there are often secrets.
_ENV_IGNORE_CHECKED=""
_warn_env_not_ignored() {
  [[ -n "$_ENV_IGNORE_CHECKED" ]] && return 0
  _ENV_IGNORE_CHECKED=1
  local dir base
  dir=$(dirname "$ENV_FILE"); base=$(basename "$ENV_FILE")
  git -C "$dir" rev-parse --is-inside-work-tree >/dev/null 2>&1 || return 0
  git -C "$dir" check-ignore -q -- "$base" && return 0
  warn "$ENV_FILE isn't gitignored; add it to .gitignore before committing"
}

# write_env KEY VALUE upserts KEY=VALUE into ENV_FILE (creates it; replaces
# any existing assignment, even one spanning lines), quoting VALUE with
# dotenv_encode. Idempotent. Fails on a value dotenv_encode can't quote.
write_env() {
  local key="$1" value="$2" encoded tmp
  if ! encoded=$(dotenv_encode "$value"); then
    printf '  %s✗ %s has a newline or '"'"' along with a ", \\, or $, which %s can'"'"'t hold; not writing it%s\n' \
      "$RED" "$key" "$ENV_FILE" "$RESET" >&2
    return 1
  fi
  _warn_env_not_ignored
  # A new .env holds secrets, so only you can read it; an existing one keeps its mode
  [[ -e "$ENV_FILE" ]] || (umask 077; touch "$ENV_FILE")
  tmp=$(mktemp)
  awk -v mode=drop -v key="$key" "$_DOTENV_AWK" "$ENV_FILE" > "$tmp"
  printf '%s=%s\n' "$key" "$encoded" >> "$tmp"
  # Write through the file rather than replace it, so a symlinked .env and its mode survive
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# Show the .env writes, GitHub secrets, and remaining manual actions.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# ──────────────────────────────────────────────────────────────────────────

TOTAL_STAGES=1

banner "Stripe setup"

# ── Example stage: replace with your real steps ───────────────────────────
stage "Stripe: API keys"
say "We'll grab your Stripe test keys and store them for local dev + CI."
open_url "https://dashboard.stripe.com/test/apikeys"
step "On the API keys page, copy the Publishable key (starts pk_test_)."
ask STRIPE_PUBLISHABLE_KEY "Paste the publishable key:"
step "Click 'Reveal test key' on the Secret key row, then copy it."
ask_secret STRIPE_SECRET_KEY "Paste the secret key:"
write_env STRIPE_PUBLISHABLE_KEY "$STRIPE_PUBLISHABLE_KEY"
write_env STRIPE_SECRET_KEY "$STRIPE_SECRET_KEY"
set_secret STRIPE_SECRET_KEY "$STRIPE_SECRET_KEY"   # CI needs this one
# ──────────────────────────────────────────────────────────────────────────

finish
